  dash: { label: 'NHLBI DASH eating plan', url: 'https://www.nhlbi.nih.gov/health/dash-eating-plan' },
  thiamin: { label: 'NIH ODS thiamin fact sheet for health professionals', url: 'https://ods.od.nih.gov/factsheets/Thiamin-HealthProfessional/' },
