  pad: { label: 'ACC 2024 lower extremity peripheral artery disease guideline key points', url: 'https://www.acc.org/latest-in-cardiology/ten-points-to-remember/2024/05/09/15/00/2024-guideline-for-lower-extremity-pad' },
